<?php declare(strict_types=1); final class ExportRepository{public function __construct(private PDO$db){}public function find(int$id):?array{$s=$this->db->prepare('SELECT * FROM exports WHERE id=? AND deleted_at IS NULL');$s->execute([$id]);return$s->fetch()?:null;}public function all():array{return$this->db->query('SELECT * FROM exports WHERE deleted_at IS NULL ORDER BY created_at DESC')->fetchAll();}}
